      key TEXT PRIMARY KEY,
      payload TEXT NOT NULL,
      job_id TEXT NOT NULL REFERENCES jobs (id)
    );
    CREATE TABLE IF NOT EXISTS heartbeat (
      name TEXT PRIMARY KEY,
      at_ms INTEGER NOT NULL
    );
  `);
