/** Job model shared by the server and the worker: validation, row shape, and the public JSON form. */

export const DEFAULT_STEPS = 5;
export const MAX_STEPS = 20;
export const MAX_FAIL_ATTEMPTS = 5;
export const MAX_INPUT_LENGTH = 1000;
export const IDEMPOTENCY_KEY_PATTERN = /^[A-Za-z0-9_-]{1,128}$/;

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

export interface FieldError {
  field: string;
  message: string;
}

/** A submission after defaults are applied. Field order matters: it is used for idempotency comparison. */
export interface NewJob {
  input: string;
  steps: number;
  failAttempts: number;
}

/** A row of the `jobs` table as returned by node:sqlite. */
export interface JobRow {
  seq: number;
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  progress_completed: number;
  result_output: string | null;
  error: string | null;
  available_at: number;
  created_at: string;
  updated_at: string;
}

export function isPlainObject(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

/** Validates a parsed request body. Returns every offending field, or the job when there are none. */
export function validateNewJob(body: unknown): { job?: NewJob; fields: FieldError[] } {
  if (!isPlainObject(body)) return { fields: [{ field: 'body', message: 'body must be a JSON object' }] };
  const fields: FieldError[] = [];
  for (const key of Object.keys(body)) {
    if (key !== 'input' && key !== 'steps' && key !== 'failAttempts') fields.push({ field: key, message: 'unknown field' });
  }

  let input = '';
  const raw = body.input;
  if (raw === undefined) {
    fields.push({ field: 'input', message: 'input is required' });
  } else if (typeof raw !== 'string') {
    fields.push({ field: 'input', message: 'input must be a string' });
  } else if (raw.length < 1 || raw.length > MAX_INPUT_LENGTH) {
    fields.push({ field: 'input', message: `input must be 1 to ${MAX_INPUT_LENGTH} characters` });
  } else if (raw.trim() === '') {
    fields.push({ field: 'input', message: 'input must not be only whitespace' });
  } else {
    input = raw;
  }

  const steps = integerField(body, 'steps', 1, MAX_STEPS, DEFAULT_STEPS, fields);
  const failAttempts = integerField(body, 'failAttempts', 0, MAX_FAIL_ATTEMPTS, 0, fields);
  if (fields.length > 0) return { fields };
  return { job: { input, steps, failAttempts }, fields };
}

function integerField(
  body: Record<string, unknown>,
  name: string,
  min: number,
  max: number,
  fallback: number,
  fields: FieldError[],
): number {
  const value = body[name];
  if (value === undefined) return fallback;
  if (typeof value !== 'number' || !Number.isInteger(value)) {
    fields.push({ field: name, message: `${name} must be an integer` });
    return fallback;
  }
  if (value < min || value > max) {
    fields.push({ field: name, message: `${name} must be between ${min} and ${max}` });
    return fallback;
  }
  return value;
}

/** The public JSON shape of a job. */
export function toJob(row: JobRow) {
  return {
    id: row.id,
    status: row.status,
    input: row.input,
    steps: row.steps,
    failAttempts: row.fail_attempts,
    attempts: row.attempts,
    progress: { completed: row.progress_completed, total: row.steps },
    result: row.status === 'completed' ? { output: row.result_output ?? '' } : null,
    error: row.status === 'failed' ? row.error : null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

