import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { randomUUID } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { openDatabase } from './db.ts';
import {
  IDEMPOTENCY_KEY_PATTERN,
  toJob,
  validateNewJob,
  type FieldError,
  type JobRow,
  type NewJob,
} from './jobs.ts';

const HEARTBEAT_FRESH_MS = 3_000;
const MAX_BODY_BYTES = 64 * 1024;

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

const stmts = {
  insertJob: db.prepare(
    `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress_completed, result_output, error, available_at, created_at, updated_at)
     VALUES (?, 'queued', ?, ?, ?, 0, 0, NULL, NULL, 0, ?, ?)`,
  ),
  jobById: db.prepare('SELECT * FROM jobs WHERE id = ?'),
  allJobs: db.prepare('SELECT * FROM jobs ORDER BY seq DESC'),
  idempotencyByKey: db.prepare('SELECT payload, job_id FROM idempotency WHERE key = ?'),
  insertIdempotency: db.prepare('INSERT INTO idempotency (key, payload, job_id) VALUES (?, ?, ?)'),
  workerHeartbeat: db.prepare("SELECT at_ms FROM heartbeat WHERE name = 'worker'"),
};

function send(res: ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...headers });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  send(res, status, { error: fields ? { code, message, fields } : { code, message } });
}

function methodNotAllowed(res: ServerResponse, allowed: string[]): void {
  sendError(res, 405, 'method_not_allowed', `Method not allowed. Allowed: ${allowed.join(', ')}.`);
}

/** Reads the request body. Resolves to null when it exceeds MAX_BODY_BYTES. */
function readBody(req: IncomingMessage): Promise<string | null> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) tooLarge = true;
      else chunks.push(chunk);
    });
    req.on('end', () => resolve(tooLarge ? null : Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

function getJobRow(id: string): JobRow | undefined {
  return stmts.jobById.get(id) as unknown as JobRow | undefined;
}

type SaveOutcome = { kind: 'conflict' } | { kind: 'saved'; created: boolean; row: JobRow };

/**
 * Creates a job, or replays one for a reused Idempotency-Key. The check and the insert happen in
 * one IMMEDIATE transaction, so concurrent submissions with the same key create at most one job.
 */
function saveJob(job: NewJob, key: string | undefined): SaveOutcome {
  const payload = JSON.stringify([job.input, job.steps, job.failAttempts]);
  db.exec('BEGIN IMMEDIATE');
  try {
    if (key !== undefined) {
      const existing = stmts.idempotencyByKey.get(key) as unknown as { payload: string; job_id: string } | undefined;
      if (existing) {
        db.exec('COMMIT');
        if (existing.payload !== payload) return { kind: 'conflict' };
        return { kind: 'saved', created: false, row: getJobRow(existing.job_id)! };
      }
    }
    const id = randomUUID();
    const now = new Date().toISOString();
    stmts.insertJob.run(id, job.input, job.steps, job.failAttempts, now, now);
    if (key !== undefined) stmts.insertIdempotency.run(key, payload, id);
    db.exec('COMMIT');
    return { kind: 'saved', created: true, row: getJobRow(id)! };
  } catch (e) {
    try {
      db.exec('ROLLBACK');
    } catch {
      // no transaction open
    }
    throw e;
  }
}

async function handleCreate(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const contentType = req.headers['content-type'] ?? '';
  if (!/^application\/json\s*(;|$)/i.test(contentType)) {
    return sendError(res, 400, 'invalid_request', 'Content-Type must be application/json.', [
      { field: 'body', message: 'Content-Type must be application/json' },
    ]);
  }
  const text = await readBody(req);
  if (text === null) {
    return sendError(res, 400, 'invalid_request', 'Request body is too large.', [{ field: 'body', message: 'body is too large' }]);
  }
  let parsed: unknown;
  try {
    parsed = JSON.parse(text);
  } catch {
    return sendError(res, 400, 'invalid_request', 'Request body is not valid JSON.', [{ field: 'body', message: 'malformed JSON' }]);
  }

  const { job, fields } = validateNewJob(parsed);
  let key: string | undefined;
  const header = req.headers['idempotency-key'];
  if (header !== undefined) {
    if (typeof header === 'string' && IDEMPOTENCY_KEY_PATTERN.test(header)) key = header;
    else fields.push({ field: 'Idempotency-Key', message: 'must match ^[A-Za-z0-9_-]{1,128}$' });
  }
  if (!job || fields.length > 0) return sendError(res, 400, 'invalid_request', 'The submission is invalid.', fields);

  const outcome = saveJob(job, key);
  if (outcome.kind === 'conflict') {
    return sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
  }
  send(res, outcome.created ? 201 : 200, toJob(outcome.row));
}

function handleHealth(res: ServerResponse): void {
  const heartbeat = stmts.workerHeartbeat.get() as unknown as { at_ms: number } | undefined;
  const worker = heartbeat !== undefined && Date.now() - heartbeat.at_ms < HEARTBEAT_FRESH_MS ? 'up' : 'down';
  send(res, 200, { status: 'ok', worker });
}

async function route(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const method = req.method ?? 'GET';
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');

  if (pathname === '/health') {
    return method === 'GET' ? handleHealth(res) : methodNotAllowed(res, ['GET']);
  }
  if (pathname === '/') {
    if (method !== 'GET') return methodNotAllowed(res, ['GET']);
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }
  if (pathname === '/api/jobs') {
    if (method === 'GET') return send(res, 200, { jobs: (stmts.allJobs.all() as unknown as JobRow[]).map(toJob) });
    if (method === 'POST') return handleCreate(req, res);
    return methodNotAllowed(res, ['GET', 'POST']);
  }
  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (match) {
    if (method !== 'GET') return methodNotAllowed(res, ['GET']);
    let id: string;
    try {
      id = decodeURIComponent(match[1]!);
    } catch {
      return sendError(res, 404, 'not_found', 'No such job.');
    }
    const row = getJobRow(id);
    return row ? send(res, 200, toJob(row)) : sendError(res, 404, 'not_found', 'No such job.');
  }
  return sendError(res, 404, 'not_found', 'No such route.');
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer((req, res) => {
  route(req, res).catch((e: unknown) => {
    console.error('request failed:', e);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal error.');
    else res.end();
  });
});

server.listen(port, () => console.log(`server listening on ${port}`));

function shutdown(): void {
  console.log('server stopping');
  const timer = setTimeout(() => process.exit(0), 2_000);
  timer.unref();
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeAllConnections();
}

process.once('SIGTERM', shutdown);
process.once('SIGINT', shutdown);

