import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase } from './db.ts';
import type { JobRow } from './jobs.ts';

const STEP_MS = 100;
const IDLE_POLL_MS = 200;
const HEARTBEAT_MS = 1_000;
const MAX_ATTEMPTS = 3;
const RETRY_DELAY_MS = 500;

const db = openDatabase();
let stopping = false;

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

const now = () => new Date().toISOString();

const stmts = {
  heartbeat: db.prepare(
    "INSERT INTO heartbeat (name, at_ms) VALUES ('worker', ?) ON CONFLICT (name) DO UPDATE SET at_ms = excluded.at_ms",
  ),
  nextQueued: db.prepare(
    "SELECT * FROM jobs WHERE status = 'queued' AND available_at <= ? ORDER BY seq LIMIT 1",
  ),
  startAttempt: db.prepare(
    "UPDATE jobs SET status = 'running', attempts = ?, progress_completed = 0, updated_at = ? WHERE id = ?",
  ),
  progress: db.prepare('UPDATE jobs SET progress_completed = ?, updated_at = ? WHERE id = ?'),
  complete: db.prepare(
    "UPDATE jobs SET status = 'completed', progress_completed = steps, result_output = ?, error = NULL, updated_at = ? WHERE id = ?",
  ),
  fail: db.prepare(
    "UPDATE jobs SET status = 'failed', result_output = NULL, error = ?, updated_at = ? WHERE id = ?",
  ),
  retry: db.prepare(
    "UPDATE jobs SET status = 'queued', progress_completed = 0, available_at = ?, updated_at = ? WHERE id = ?",
  ),
  requeue: db.prepare(
    "UPDATE jobs SET status = 'queued', progress_completed = 0, updated_at = ? WHERE id = ?",
  ),
  requeueOrphans: db.prepare(
    "UPDATE jobs SET status = 'queued', progress_completed = 0, updated_at = ? WHERE status = 'running'",
  ),
};

function beat(atMs: number): void {
  try {
    stmts.heartbeat.run(atMs);
  } catch (e) {
    console.error('heartbeat failed:', e);
  }
}

/** Runs one processing attempt for a queued job, recording progress and the outcome. */
async function processJob(job: JobRow): Promise<void> {
  const attempt = job.attempts + 1;
  stmts.startAttempt.run(attempt, now(), job.id);

  if (attempt <= job.fail_attempts) {
    // Simulated transient failure: the first step fails before any progress is made.
    await sleep(STEP_MS);
    if (stopping) return requeue(job.id);
    if (attempt >= MAX_ATTEMPTS) stmts.fail.run('transient failure', now(), job.id);
    else stmts.retry.run(Date.now() + RETRY_DELAY_MS, now(), job.id);
    return;
  }

  for (let completed = 1; completed <= job.steps; completed++) {
    await sleep(STEP_MS);
    if (stopping) return requeue(job.id);
    stmts.progress.run(completed, now(), job.id);
  }
  stmts.complete.run(job.input.toUpperCase(), now(), job.id);
}

/** Puts an interrupted attempt back on the queue so the next worker start processes it again. */
function requeue(id: string): void {
  stmts.requeue.run(now(), id);
}

async function main(): Promise<void> {
  // A "running" job here was left behind by a worker that died mid-attempt.
  stmts.requeueOrphans.run(now());
  beat(Date.now());
  const heartbeat = setInterval(() => beat(Date.now()), HEARTBEAT_MS);
  console.log('worker started');

  while (!stopping) {
    try {
      const job = stmts.nextQueued.get(Date.now()) as unknown as JobRow | undefined;
      if (job) await processJob(job);
      else await sleep(IDLE_POLL_MS);
    } catch (e) {
      console.error('processing error:', e);
      await sleep(IDLE_POLL_MS);
    }
  }

  clearInterval(heartbeat);
  beat(0);
  db.close();
  console.log('worker stopped');
}

await main();

